sys_variable_value.value:
(function execute(inputs, outputs) {
    var requestType = inputs.request_type || '';
    var urgency = inputs.urgency || '';

    try {
        var dtApi = new sn_dt.DecisionTableAPI();
        var dtInputs = {
            u_request_type: requestType,
            u_urgency: urgency
        };
        var result = dtApi.getDecision('bf5a9df0c3ce83901ff35d02b401317a', dtInputs);

        if (result && result.length > 0) {
            var decision = result[0];
            var dtPriority = decision.u_priority ? decision.u_priority.toString() : '';

            if (dtPriority && dtPriority !== 'medium') {
                // Decision table returned a specific non-default priority override
                outputs.priority = dtPriority;
            } else {
                // Decision table returned the default (medium) or no priority
                // Use urgency as priority for unmatched combinations
                outputs.priority = urgency || 'medium';
            }
        } else {
            // No result from decision table - use urgency as priority
            outputs.priority = urgency || 'medium';
        }
    } catch (e) {
        gs.error('Determine Priority - Error: ' + e.message);
        outputs.priority = urgency || 'medium';
    }
})(inputs, outputs);

